insert into public.questions (question_text, answers, correct_answer, explanation, category, state, image_url, question_text_es, answers_es, explanation_es) values ($q$What does this sign mean?$q$, $q${"A": "Hospital nearby", "B": "Railroad crossing", "C": "School crossing", "D": "Emergency vehicles"}$q$::jsonb, $q$D$q$, $q$This warning sign indicates a fire station or emergency vehicles may be entering or crossing the roadway ahead. Be alert for emergency vehicles.$q$, $q$Signs, Signals & Markings$q$, null, $q$https://ksiqvvoqlzdihjubaxbm.supabase.co/storage/v1/object/public/images/Questions/Generated/mutcd-w11-8.png$q$, $q$¿Qué significa esta señal?$q$, $q${"A": "Hospital cercano", "B": "Cruce de ferrocarril", "C": "Cruce escolar", "D": "Vehículos de emergencia"}$q$::jsonb, $q$Esta señal de advertencia indica una estación de bomberos o que vehículos de emergencia pueden entrar o cruzar la vía más adelante. Manténgase alerta.$q$);
insert into public.questions (question_text, answers, correct_answer, explanation, category, state, image_url, question_text_es, answers_es, explanation_es) values ($q$What should you do when you see this sign?$q$, $q${"A": "Turn on headlights", "B": "Yield to all traffic", "C": "Watch for fire trucks", "D": "Stop at the sign"}$q$::jsonb, $q$C$q$, $q$This sign warns that emergency vehicles may be entering or crossing ahead. Slow down if needed and watch for emergency vehicles.$q$, $q$Signs, Signals & Markings$q$, null, $q$https://ksiqvvoqlzdihjubaxbm.supabase.co/storage/v1/object/public/images/Questions/Generated/mutcd-w11-8.png$q$, $q$¿Qué debe hacer al ver esta señal?$q$, $q${"A": "Encienda los faros", "B": "Ceda a todo el tráfico", "C": "Cuidado con bomberos", "D": "Pare en la señal"}$q$::jsonb, $q$Esta señal advierte que vehículos de emergencia pueden entrar o cruzar más adelante. Reduzca la velocidad si es necesario y esté atento.$q$);
insert into public.questions (question_text, answers, correct_answer, explanation, category, state, image_url, question_text_es, answers_es, explanation_es) values ($q$When you see this sign, what should you do in the left lane?$q$, $q${"A": "Go straight only", "B": "Merge right", "C": "Turn left only", "D": "Yield to oncoming"}$q$::jsonb, $q$C$q$, $q$This advance lane control sign tells you the left lane is for left turns only. The right lane may turn left or continue straight.$q$, $q$Signs, Signals & Markings$q$, null, $q$https://ksiqvvoqlzdihjubaxbm.supabase.co/storage/v1/object/public/images/Questions/Generated/mutcd-r3-8.png$q$, $q$Cuando vea esta señal, ¿qué debe hacer en el carril izquierdo?$q$, $q${"A": "Solo seguir recto", "B": "Pasar a la derecha", "C": "Solo girar a la izq.", "D": "Ceder al de enfrente"}$q$::jsonb, $q$Esta señal de control de carriles indica que el carril izquierdo es solo para dar vuelta a la izquierda. El carril derecho puede doblar a la izquierda o seguir recto.$q$);
insert into public.questions (question_text, answers, correct_answer, explanation, category, state, image_url, question_text_es, answers_es, explanation_es) values ($q$When you see this sign, what should you do?$q$, $q${"A": "Use headlights now", "B": "Merge into traffic", "C": "Prepare to stop", "D": "Slow down on wet road"}$q$::jsonb, $q$D$q$, $q$This sign warns that the road may be slippery when wet. Reduce speed and use extra caution in rainy or wet conditions.$q$, $q$Signs, Signals & Markings$q$, null, $q$https://ksiqvvoqlzdihjubaxbm.supabase.co/storage/v1/object/public/images/Questions/Generated/mutcd-w8-5.png$q$, $q$Cuando vea esta señal, ¿qué debe hacer?$q$, $q${"A": "Encender los faros", "B": "Incorporarse", "C": "Prepararse a parar", "D": "Reducir si está mojado"}$q$::jsonb, $q$Esta señal advierte que la carretera puede estar resbaladiza cuando está mojada. Reduzca la velocidad y maneje con más precaución en condiciones húmedas o de lluvia.$q$);
insert into public.questions (question_text, answers, correct_answer, explanation, category, state, image_url, question_text_es, answers_es, explanation_es) values ($q$What does this sign mean?$q$, $q${"A": "Keep right", "B": "Two-way traffic", "C": "Road curves left", "D": "Winding road ahead"}$q$::jsonb, $q$C$q$, $q$This chevron alignment sign marks a sharp change in road direction. Here, it shows the road curves to the left.$q$, $q$Signs, Signals & Markings$q$, null, $q$https://ksiqvvoqlzdihjubaxbm.supabase.co/storage/v1/object/public/images/Questions/Generated/mutcd-w1-8.png$q$, $q$¿Qué significa esta señal?$q$, $q${"A": "Manténgase a la der.", "B": "Tráfico doble sentido", "C": "La vía gira a la izq.", "D": "Camino sinuoso"}$q$::jsonb, $q$Esta señal de alineación con chevrones marca un cambio fuerte en la dirección de la vía. Aquí muestra que la vía gira a la izquierda.$q$);
insert into public.questions (question_text, answers, correct_answer, explanation, category, state, image_url, question_text_es, answers_es, explanation_es) values ($q$What should you do when you see this sign?$q$, $q${"A": "Stop at the crossing", "B": "Pass on the right", "C": "Merge into traffic", "D": "Follow the left curve"}$q$::jsonb, $q$D$q$, $q$The chevrons guide drivers through the curve. Slow as needed and follow the roadway to the left.$q$, $q$Signs, Signals & Markings$q$, null, $q$https://ksiqvvoqlzdihjubaxbm.supabase.co/storage/v1/object/public/images/Questions/Generated/mutcd-w1-8.png$q$, $q$¿Qué debe hacer al ver esta señal?$q$, $q${"A": "Deténgase en el cruce", "B": "Pase por la derecha", "C": "Incorpórese al tráfico", "D": "Siga curva a la izq."}$q$::jsonb, $q$Los chevrones guían a los conductores a través de la curva. Reduzca la velocidad si es necesario y siga la vía hacia la izquierda.$q$);
insert into public.questions (question_text, answers, correct_answer, explanation, category, state, image_url, question_text_es, answers_es, explanation_es) values ($q$This sign is posted ahead. What should you do?$q$, $q${"A": "Expect merge on left", "B": "Yield to cross traffic", "C": "Keep right only", "D": "Turn left soon"}$q$::jsonb, $q$A$q$, $q$This sign warns that traffic from the left will merge into your lane ahead. Slow if needed and be ready to adjust space for merging vehicles.$q$, $q$Signs, Signals & Markings$q$, null, $q$https://ksiqvvoqlzdihjubaxbm.supabase.co/storage/v1/object/public/images/Questions/Generated/mutcd-w4-1.png$q$, $q$Esta señal está colocada más adelante. ¿Qué debe hacer?$q$, $q${"A": "Prevea unión por izq.", "B": "Ceda en el cruce", "C": "Solo carril derecho", "D": "Gire a la izq. pronto"}$q$::jsonb, $q$Esta señal advierte que el tráfico de la izquierda se unirá a su carril más adelante. Reduzca la velocidad si es necesario y esté listo para dejar espacio a los vehículos que entran.$q$);
insert into public.questions (question_text, answers, correct_answer, explanation, category, state, image_url, question_text_es, answers_es, explanation_es) values ($q$What does this sign mean?$q$, $q${"A": "Road curves right", "B": "Sharp left turn", "C": "One-way traffic", "D": "Hidden driveway"}$q$::jsonb, $q$B$q$, $q$This large arrow warns that the road ahead turns sharply to the left. Slow down and be ready to follow the turn.$q$, $q$Signs, Signals & Markings$q$, null, $q$https://ksiqvvoqlzdihjubaxbm.supabase.co/storage/v1/object/public/images/Questions/Generated/mutcd-w1-6.png$q$, $q$¿Qué significa esta señal?$q$, $q${"A": "Curva a la derecha", "B": "Giro cerrado a la izq.", "C": "Tránsito en un sentido", "D": "Entrada oculta"}$q$::jsonb, $q$Esta flecha grande advierte que la carretera adelante gira bruscamente a la izquierda. Reduzca la velocidad y prepárese para seguir la curva.$q$);
insert into public.questions (question_text, answers, correct_answer, explanation, category, state, image_url, question_text_es, answers_es, explanation_es) values ($q$What should you do when you see this sign?$q$, $q${"A": "Pass with caution", "B": "Stop at the sign", "C": "Slow for sharp left", "D": "Merge right now"}$q$::jsonb, $q$C$q$, $q$This sign warns of a sharp left turn ahead. Reduce speed and prepare to steer through the turn safely.$q$, $q$Signs, Signals & Markings$q$, null, $q$https://ksiqvvoqlzdihjubaxbm.supabase.co/storage/v1/object/public/images/Questions/Generated/mutcd-w1-6.png$q$, $q$¿Qué debe hacer al ver esta señal?$q$, $q${"A": "Rebase con cuidado", "B": "Deténgase en la señal", "C": "Reduzca por el giro", "D": "Incorpórese a la der."}$q$::jsonb, $q$Esta señal advierte de una vuelta cerrada a la izquierda más adelante. Reduzca la velocidad y prepárese para girar con seguridad.$q$);
